RDATA_TAIL_0x1180 = bytes.fromhex(
    ''
)

def build_rdata() -> bytes:
    if len(ROUTE_SLOTS_368) != 368: raise ValueError('route slots')
    if len(PROBE_SEMANTIC_RECORDS_342) != 342: raise ValueError('probe records')
    out=bytearray(0x1180)
    out[:0x170]=bytes(ROUTE_SLOTS_368)
    p=0x170
    for rec in PROBE_SEMANTIC_RECORDS_342:
        struct.pack_into('<3I',out,p,*rec); p+=12
    # historical 8-byte alignment pad at 0x1178..0x117f remains zero
    out += RDATA_TAIL_0x1180
    if len(out)!=0x2000: raise ValueError(hex(len(out)))
    return bytes(out)
